function romanToInt(s) {
  let sum = 0;
  let next = null;
  const romanArr = {
    I: 1,
    V: 5,
    X: 10,
    L: 50,
    C: 100,
    D: 500,
    M: 1000
  };
  for (let i = 0; i < s.length; i++) {
    next = s[i + 1] || null;
    const curr = s[i];
    if (romanArr[next] > romanArr[curr]) {
      sum -= romanArr[curr];
      continue;
    }
    sum += romanArr[curr];
  }
  return sum;
}

